const CURSE_SURCHARGE = 0.5;

// Item-specific modifiers are charged as a percentage of the affected item's
// OWN base premium, unlike policy-wide modifiers which scale the policy base.
const surchargeOn = (item: Item, rate: number): number =>
  basePremiumOf(item) * rate;

const surchargesOn = (item: Item): number =>
  item.cursed ? surchargeOn(item, CURSE_SURCHARGE) : 0;

const itemSurchargesOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + surchargesOn(item), 0);

